import React, { useState, useEffect, useMemo } from "react";
import {
  Container,
  Row,
  Col,
  Card,
  CardHeader,
  CardBody,
  Table,
  Button,
  Modal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  FormGroup,
  Label,
  Input,
  Pagination,
  PaginationItem,
  PaginationLink,
} from "reactstrap";
import { Link } from "react-router-dom";
import BreadCrumb from "../../Components/Common/BreadCrumb";
import SimpleBar from "simplebar-react";
import { toast, ToastContainer } from "react-toastify";

// Import your API client
import {  getAllCategories, updateCategory, deleteCategory, createCategory } from "../../api";


const ManageCategory = () => {
  document.title = "Manage Categories";

  // State to hold the list of categories, initially empty
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true); // New loading state
  const [error, setError] = useState(null); // New error state

  // Pagination states
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10); // You can adjust this number

  // State for Add/Edit Category Modal visibility
  const [modal, setModal] = useState(false);
  const [isEdit, setIsEdit] = useState(false); // To determine if the modal is for edit or add

  // State for the category being edited/added
  const [currentCategory, setCurrentCategory] = useState({
    id: null,
    sequenceNumber: "",
    name: "",
  });

  // --- NEW STATES FOR DELETE CONFIRMATION MODAL ---
  const [deleteModal, setDeleteModal] = useState(false);
  const [categoryToDelete, setCategoryToDelete] = useState(null); // Holds the category object to be deleted
  // --- END NEW STATES ---

  // Function to fetch categories from the backend
  const fetchCategories = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await getAllCategories();
      setCategories(data);
    } catch (err) {
      setError(err.message || "An unknown error occurred");
      console.error("Failed to fetch categories:", err);
    } finally {
      setLoading(false);
    }
  };

  // useEffect to fetch data when the component mounts
  useEffect(() => {
    fetchCategories();
  }, []); // Empty dependency array means this runs once on mount

  // Calculate total pages (re-calculates when categories change)
  const totalPages = useMemo(
    () => Math.ceil(categories.length / itemsPerPage),
    [categories.length, itemsPerPage]
  );

  // Get current items for the table (re-calculates when categories or page changes)
  const currentItems = useMemo(() => {
    // Ensure categories are sorted before slicing for pagination
    const sortedCategories = [...categories].sort(
      (a, b) => a.sequenceNumber - b.sequenceNumber
    );
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    return sortedCategories.slice(indexOfFirstItem, indexOfLastItem);
  }, [categories, currentPage, itemsPerPage]);

  // Change page
  const paginate = (pageNumber) => {
    if (pageNumber > 0 && pageNumber <= totalPages) {
      setCurrentPage(pageNumber);
    }
  };

  // Toggle for Add/Edit Category Modal
  const toggleModal = () => {
    setModal(!modal);
    // If modal is closing, reset currentCategory and isEdit state
    if (modal) {
      setCurrentCategory({ id: null, sequenceNumber: "", name: "" });
      setIsEdit(false);
    }
  };

  // Handle Edit button click
  const handleEdit = (category) => {
    setCurrentCategory(category);
    setIsEdit(true);
    toggleModal();
  };

  // --- NEW DELETE MODAL HANDLERS ---

  // Opens the delete confirmation modal
  const handleDeleteClick = (category) => {
    setCategoryToDelete(category); // Store the category to be deleted
    setDeleteModal(true); // Open the delete confirmation modal
  };

  // Closes the delete confirmation modal
  const handleCancelDelete = () => {
    setDeleteModal(false);
    setCategoryToDelete(null); // Clear the category to be deleted
  };

  // Confirms deletion and calls the API
  const handleConfirmDelete = async () => {
    if (categoryToDelete) {
      try {
        await deleteCategory(categoryToDelete.id); // Call the API to soft delete
        console.log(
          `Category ID ${categoryToDelete.id} soft-deleted successfully.`
        );
        toast.success("Category deleted successfully!");

        // After successful soft delete, re-fetch categories to update the UI
        await fetchCategories();

        // Recalculate total pages and adjust currentPage if necessary
        // Filter out the deleted category from current list to get an accurate new count
        const remainingCategories = categories.filter(
          (cat) => cat.id !== categoryToDelete.id
        );
        const newTotalPages = Math.ceil(
          remainingCategories.length / itemsPerPage
        );

        if (currentPage > newTotalPages && newTotalPages > 0) {
          setCurrentPage(newTotalPages);
        } else if (newTotalPages === 0) {
          setCurrentPage(1); // Reset to page 1 if all items deleted
        }

        handleCancelDelete(); // Close the modal and clear state
      } catch (deleteError) {
        console.error("Error soft-deleting category:", deleteError);
        toast.error(deleteError.message || "Failed to delete category.");
        setError(deleteError.message || "Failed to delete category.");
        handleCancelDelete(); // Close modal even on error
      }
    }
  };
  // --- END NEW DELETE MODAL HANDLERS ---

  // Handle form submission for adding/editing a category (Will need API calls)
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (isEdit) {
        await updateCategory(currentCategory.id, {
          sequenceNumber: parseInt(currentCategory.sequenceNumber),
          name: currentCategory.name,
        });
        console.log("Category updated successfully!");
        toast.success("Category updated successfully!");
      } else {
        // UNCOMMENT AND USE THIS LINE FOR ADDING NEW CATEGORY
        await createCategory({
          sequenceNumber: parseInt(currentCategory.sequenceNumber), // Ensure it's a number
          name: currentCategory.name,
        });
        console.log("Category added successfully!");
        toast.success("Category added successfully!");
      }

      await fetchCategories(); // Re-fetch categories to update the list
      setCurrentCategory({ id: null, sequenceNumber: "", name: "" }); // Reset form
      setIsEdit(false); // Reset edit state
      toggleModal(); // Close modal after submission
    } catch (submitError) {
      console.error("Error submitting category:", submitError);
      toast.error(submitError.message || "Failed to save category.");
      setError(submitError.message || "Failed to save category.");
    }
  };

  // Handle input changes in the modal form
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setCurrentCategory({ ...currentCategory, [name]: value });
  };

  return (
    <React.Fragment>
      <ToastContainer
        position="top-right"
        autoClose={5000}
        hideProgressBar={false}
        closeOnClick
        pauseOnHover
        draggable
        pauseOnFocusLoss
      />
      <div className="page-content">
        <Container fluid>
          <BreadCrumb title="Manage Categories" pageTitle="Master" />

          <Row className="mt-2">
            <Col lg={12}>
              <Card>
                <CardHeader className="d-flex justify-content-between align-items-center">
                  <h5 className="card-title mb-0">Category List</h5>
                  <Button
                    color="primary"
                    onClick={() => {
                      setIsEdit(false);
                      toggleModal();
                    }}
                  >
                    Add New Category
                  </Button>
                </CardHeader>
                <CardBody>
                  {loading ? (
                    <div className="text-center">Loading categories...</div>
                  ) : error ? (
                    <div className="text-center text-danger">
                      Error: {error}
                    </div>
                  ) : (
                    <SimpleBar
                      style={{ maxHeight: "400px", overflowX: "auto" }}
                    >
                      <Table className="table-bordered table-nowrap mb-0">
                        <thead>
                          <tr>
                            <th scope="col">Sequence Number</th>
                            <th scope="col">Name</th>
                            <th scope="col" style={{ width: "120px" }}>
                              Actions
                            </th>
                          </tr>
                        </thead>
                        <tbody>
                          {currentItems.length > 0 ? (
                            currentItems.map((category) => (
                              <tr key={category.id}>
                                <td>{category.sequenceNumber}</td>
                                <td>{category.name}</td>
                                <td>
                                  <div className="d-flex gap-2">
                                    <Button
                                      color="info"
                                      size="sm"
                                      onClick={() => handleEdit(category)}
                                    >
                                      Edit
                                    </Button>
                                    <Button
                                      color="danger"
                                      size="sm"
                                      onClick={() =>
                                        handleDeleteClick(category)
                                      }
                                    >
                                      Delete
                                    </Button>
                                  </div>
                                </td>
                              </tr>
                            ))
                          ) : (
                            <tr>
                              <td colSpan="3" className="text-center">
                                No categories found.
                              </td>
                            </tr>
                          )}
                        </tbody>
                      </Table>
                    </SimpleBar>
                  )}

                  {/* Pagination Controls */}
                  {totalPages > 1 && !loading && !error && (
                    <div className="d-flex justify-content-end mt-3">
                      <Pagination>
                        <PaginationItem disabled={currentPage === 1}>
                          <PaginationLink
                            previous
                            onClick={() => paginate(currentPage - 1)}
                          />
                        </PaginationItem>
                        {[...Array(totalPages)].map((_, i) => (
                          <PaginationItem
                            key={i + 1}
                            active={i + 1 === currentPage}
                          >
                            <PaginationLink onClick={() => paginate(i + 1)}>
                              {i + 1}
                            </PaginationLink>
                          </PaginationItem>
                        ))}
                        <PaginationItem disabled={currentPage === totalPages}>
                          <PaginationLink
                            next
                            onClick={() => paginate(currentPage + 1)}
                          />
                        </PaginationItem>
                      </Pagination>
                    </div>
                  )}
                </CardBody>
              </Card>
            </Col>
          </Row>
        </Container>
      </div>

      {/* Add/Edit Category Modal */}
      <Modal isOpen={modal} toggle={toggleModal} centered>
        <ModalHeader toggle={toggleModal}>
          {isEdit ? "Edit Category" : "Add New Category"}
        </ModalHeader>
        <form onSubmit={handleSubmit}>
          <ModalBody>
            <FormGroup className="mb-3">
              <Label for="sequenceNumber">Sequence Number</Label>
              <Input
                type="number"
                id="sequenceNumber"
                name="sequenceNumber"
                value={currentCategory.sequenceNumber}
                onChange={handleInputChange}
                required
                min="1"
              />
            </FormGroup>
            <FormGroup className="mb-3">
              <Label for="name">Category Name</Label>
              <Input
                type="text"
                id="name"
                name="name"
                value={currentCategory.name}
                onChange={handleInputChange}
                required
              />
            </FormGroup>
          </ModalBody>
          <ModalFooter>
            <Button color="light" onClick={toggleModal}>
              Cancel
            </Button>
            <Button color="primary" type="submit">
              {isEdit ? "Update Category" : "Add Category"}
            </Button>
          </ModalFooter>
        </form>
      </Modal>

      {/* --- NEW DELETE CONFIRMATION MODAL --- */}
      <Modal isOpen={deleteModal} toggle={handleCancelDelete} centered>
        <ModalHeader toggle={handleCancelDelete}>Confirm Deletion</ModalHeader>
        <ModalBody>
          <p>
            Are you sure you want to soft-delete category{" "}
            <strong>{categoryToDelete?.name}</strong>?
          </p>
          <div className="d-flex justify-content-end gap-2 mt-4">
            <Button color="secondary" onClick={handleCancelDelete}>
              Cancel
            </Button>
            <Button color="danger" onClick={handleConfirmDelete}>
              Delete
            </Button>
          </div>
        </ModalBody>
      </Modal>
      {/* --- END NEW DELETE CONFIRMATION MODAL --- */}
    </React.Fragment>
  );
};

export default ManageCategory;
