import React, { useState, useEffect, useMemo, useCallback } from "react";
import {
  Container,
  Row,
  Col,
  Card,
  CardHeader,
  CardBody,
  Table,
  Button,
  Modal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  FormGroup,
  Label,
  Input,
  Pagination,
  PaginationItem,
  PaginationLink,
} from "reactstrap";
import { toast, ToastContainer } from 'react-toastify';
import BreadCrumb from "../../Components/Common/BreadCrumb";
import { useCategoryData, getPrimaryTasks, createPrimaryTask, updatePrimaryTask, deletePrimaryTask } from "../../api";
import { t } from "i18next";



const AddPrimaryTask = () => {
  document.title = "Manage Primary Tasks";

  // Use the custom hook to get category data and lookup functions
  const {
    primaryCategories,
    subCategories,
    getPrimaryCategoryName,
    getSubCategory,
    getSubCategoryName,
    loadingCategories,
    errorCategories,
  } = useCategoryData();

  const [primaryTasks, setPrimaryTasks] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(5);

  const [modal, setModal] = useState(false); // For Add/Edit Task Modal
  const [isEdit, setIsEdit] = useState(false);

  // State for custom confirmation modal
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [confirmMessage, setConfirmMessage] = useState("");
  const [confirmCallback, setConfirmCallback] = useState(null);

  // State for custom alert modal
  const [showAlertModal, setShowAlertModal] = useState(false);
  const [alertMessage, setAlertMessage] = useState("");

  const [currentPrimaryTask, setCurrentPrimaryTask] = useState({
    id: null,
    subCategoryId: "", // Keep as string for select input value
    primaryCategoryName: "", // This will be set by effect based on subCategoryId for display
    taskName: "",
    orderNumber: "",
    daysNeeded: "",
    manhourNeeded: "",
  });

  // Function to show custom alert modal
  const showCustomAlert = useCallback((message) => {
    setAlertMessage(message);
    setShowAlertModal(true);
  }, []);

  // Function to show custom confirmation modal
  const showCustomConfirm = useCallback((message, callback) => {
    setConfirmMessage(message);
    setConfirmCallback(() => callback); // Store the callback to execute on confirmation
    setShowConfirmModal(true);
  }, []);

  // Fetch primary tasks on component mount
  useEffect(() => {
    const fetchTasks = async () => {
      try {
        const tasks = await getPrimaryTasks();
        setPrimaryTasks(tasks);
      } catch (error) {
        console.error("Failed to fetch primary tasks:", error);
        showCustomAlert("Failed to fetch primary tasks. Please try again.");
      }
    };
    fetchTasks();
  }, [showCustomAlert]);

  // Effect to update primaryCategoryName when subCategoryId changes in the form
  useEffect(() => {
    if (
      currentPrimaryTask.subCategoryId !== "" &&
      !loadingCategories &&
      !errorCategories
    ) {
      const selectedSubCategory = getSubCategory(
        parseInt(currentPrimaryTask.subCategoryId, 10) // Ensure ID is integer for lookup
      );
      if (selectedSubCategory) {
        const primaryCatName = getPrimaryCategoryName(
          selectedSubCategory.primary_category_id // Use primary_category_id from subCategory object
        );
        setCurrentPrimaryTask((prevState) => ({
          ...prevState,
          primaryCategoryName: primaryCatName || "N/A", // Default to 'N/A' if not found
        }));
      } else {
        setCurrentPrimaryTask((prevState) => ({
          ...prevState,
          primaryCategoryName: "N/A",
        }));
      }
    } else if (currentPrimaryTask.subCategoryId === "") {
      setCurrentPrimaryTask((prevState) => ({
        ...prevState,
        primaryCategoryName: "",
      }));
    }
  }, [
    currentPrimaryTask.subCategoryId,
    getSubCategory,
    getPrimaryCategoryName,
    loadingCategories,
    errorCategories,
  ]);

  const totalPages = useMemo(
    () => Math.ceil(primaryTasks.length / itemsPerPage),
    [primaryTasks.length, itemsPerPage]
  );

  const currentItems = useMemo(() => {
    // Sort by orderNumber for consistent pagination
    const sortedPrimaryTasks = [...primaryTasks].sort(
      (a, b) => (a.order_number || 0) - (b.order_number || 0) // Use order_number from fetched data
    );
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    return sortedPrimaryTasks.slice(indexOfFirstItem, indexOfLastItem);
  }, [primaryTasks, currentPage, itemsPerPage]);

  const paginate = (pageNumber) => {
    if (pageNumber > 0 && pageNumber <= totalPages) {
      setCurrentPage(pageNumber);
    }
  };

  const toggleModal = () => {
    setModal(!modal);
    if (modal) {
      // Reset form when closing modal
      setCurrentPrimaryTask({
        id: null,
        subCategoryId: "",
        primaryCategoryName: "",
        taskName: "",
        orderNumber: "",
        daysNeeded: "",
        manhourNeeded: "",
      });
      setIsEdit(false);
    }
  };

  const handleEdit = (task) => {
    // When editing, populate the form with existing task data
    // The primaryCategoryName will be derived by the useEffect based on subCategoryId
    setCurrentPrimaryTask({
      id: task.id,
      subCategoryId: task.sub_category_id.toString(), // Convert to string for select input
      primaryCategoryName: task.primary_category_name || "", // Use actual fetched name
      taskName: task.task_name,
      orderNumber: task.order_number,
      daysNeeded: task.days_needed,
      manhourNeeded: task.manhour_needed,
    });
    setIsEdit(true);
    toggleModal();
  };

  const handleDelete = async (id) => {
    showCustomConfirm("Are you sure you want to soft-delete this Primary Task? It will be marked as inactive.", async () => {
      try {
        await deletePrimaryTask(id);
        // Filter out the soft-deleted task from the display
        setPrimaryTasks(primaryTasks.filter((task) => task.id !== id));
        // Adjust pagination if the last item on a page was deleted
        const newTotalPages = Math.ceil(
          (primaryTasks.length - 1) / itemsPerPage
        );
        if (currentPage > newTotalPages && newTotalPages > 0) {
          setCurrentPage(newTotalPages);
        } else if (newTotalPages === 0) {
          setCurrentPage(1);
        }
        showCustomAlert("Primary Task soft-deleted successfully!");
      } catch (error) {
        console.error("Failed to soft-delete primary task:", error);
        showCustomAlert("Error deleting task. Please try again.");
      }
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Basic form validation
    if (
      !currentPrimaryTask.subCategoryId ||
      !currentPrimaryTask.taskName ||
      currentPrimaryTask.orderNumber === "" || // Check for empty string for number inputs
      currentPrimaryTask.daysNeeded === "" ||
      currentPrimaryTask.manhourNeeded === ""
    ) {
      showCustomAlert("Please fill in all fields.");
      return;
    }

    try {
      // Prepare data to send to API (only send subCategoryId, not names)
      const taskData = {
        sub_category_id: parseInt(currentPrimaryTask.subCategoryId, 10),
        task_name: currentPrimaryTask.taskName,
        order_number: parseInt(currentPrimaryTask.orderNumber, 10),
        days_needed: parseFloat(currentPrimaryTask.daysNeeded), // Use parseFloat for potential decimals
        manhour_needed: parseFloat(currentPrimaryTask.manhourNeeded), // Use parseFloat for potential decimals
      };

      let responseTask;
      if (isEdit) {
        responseTask = await updatePrimaryTask(
          currentPrimaryTask.id,
          taskData
        );
        // Update the state with the response from the API
        setPrimaryTasks(
          primaryTasks.map((task) =>
            task.id === responseTask.id ? responseTask : task
          )
        );
        showCustomAlert("Primary Task updated successfully!");
      } else {
        responseTask = await createPrimaryTask(taskData);
        // Add the new task to the state
        setPrimaryTasks([...primaryTasks, responseTask]);
        showCustomAlert("Primary Task added successfully!");
      }

      // Reset form and close modal
      setCurrentPrimaryTask({
        id: null,
        subCategoryId: "",
        primaryCategoryName: "",
        taskName: "",
        orderNumber: "",
        daysNeeded: "",
        manhourNeeded: "",
      });
      setIsEdit(false);
      toggleModal();
    } catch (error) {
      console.error("Failed to save primary task:", error);
      showCustomAlert("Error saving task. Please try again.");
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setCurrentPrimaryTask({ ...currentPrimaryTask, [name]: value });
  };

  // --- CRITICAL PLACEMENT: Ensure these are at the top of the return block ---
  if (loadingCategories) {
    return (
      <div className="page-content">
        <Container fluid>
          <p>Loading categories...</p> {/* Or a proper spinner */}
        </Container>
      </div>
    );
  }

  if (errorCategories) {
    return (
      <div className="page-content">
        <Container fluid>
          <p style={{ color: "red" }}>
            Error loading categories: {errorCategories.message || "Unknown error"}
          </p>
        </Container>
      </div>
    );
  }
  // --- END CRITICAL PLACEMENT ---

  return (
    <React.Fragment>
        <ToastContainer
                    position="top-right"
                    autoClose={5000}
                    hideProgressBar={false}
                    closeOnClick
                    pauseOnHover
                    draggable
                    pauseOnFocusLoss
                />
      <div className="page-content">
        <Container fluid>
          <BreadCrumb title="Manage Primary Tasks" pageTitle="Master" />

          <Row className="mt-2">
            <Col lg={12}>
              <Card>
                <CardHeader className="d-flex justify-content-between align-items-center">
                  <h5 className="card-title mb-0">Primary Task List</h5>
                  <Button
                    color="primary"
                    onClick={() => {
                      setIsEdit(false);
                      toggleModal();
                    }}
                  >
                    Add New Primary Task
                  </Button>
                </CardHeader>
                <CardBody>
                  <div className="table-responsive">
                    <Table className="table-bordered table-nowrap mb-0">
                      <thead>
                        <tr>
                          <th scope="col">Order Number</th>
                          <th scope="col">Task Name</th>
                          <th scope="col">Sub Category</th>
                          <th scope="col">Primary Category</th>
                          <th scope="col">Days Needed</th>
                          <th scope="col">Manhour Needed</th>
                          <th scope="col" style={{ width: "120px" }}>
                            Actions
                          </th>
                        </tr>
                      </thead>
                      <tbody>
                        {currentItems.length > 0 ? (
                          currentItems.map((task) => {
                            // Use the names directly from the task object if available
                            // Otherwise, fallback to lookup functions (though API should provide them now)
                            const displaySubCategoryName = task.sub_category_name || getSubCategoryName(task.sub_category_id);
                            const displayPrimaryCategoryName = task.primary_category_name || (
                                getSubCategory(task.sub_category_id)
                                ? getPrimaryCategoryName(getSubCategory(task.sub_category_id).primary_category_id)
                                : "N/A"
                            );

                            return (
                              <tr key={task.id}>
                                <td>{task.order_number}</td>
                                <td>{task.task_name}</td>
                                <td>{displaySubCategoryName}</td>
                                <td>{displayPrimaryCategoryName}</td>
                                <td>{task.days_needed}</td>
                                <td>{task.manhour_needed}</td>
                                <td>
                                  <div className="d-flex gap-2">
                                    <Button
                                      color="info"
                                      size="sm"
                                      onClick={() => handleEdit(task)}
                                    >
                                      Edit
                                    </Button>
                                    <Button
                                      color="danger"
                                      size="sm"
                                      onClick={() => handleDelete(task.id)}
                                    >
                                      Delete
                                    </Button>
                                  </div>
                                </td>
                              </tr>
                            );
                          })
                        ) : (
                          <tr>
                            <td colSpan="7" className="text-center">
                              No Primary Tasks found.
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </Table>
                  </div>

                  {/* Pagination Controls */}
                  {totalPages > 1 && (
                    <div className="d-flex justify-content-end mt-3">
                      <Pagination>
                        <PaginationItem disabled={currentPage === 1}>
                          <PaginationLink
                            previous
                            onClick={() => paginate(currentPage - 1)}
                          />
                        </PaginationItem>
                        {[...Array(totalPages)].map((_, i) => (
                          <PaginationItem
                            key={i + 1}
                            active={i + 1 === currentPage}
                          >
                            <PaginationLink onClick={() => paginate(i + 1)}>
                              {i + 1}
                            </PaginationLink>
                          </PaginationItem>
                        ))}
                        <PaginationItem disabled={currentPage === totalPages}>
                          <PaginationLink
                            next
                            onClick={() => paginate(currentPage + 1)}
                          />
                        </PaginationItem>
                      </Pagination>
                    </div>
                  )}
                </CardBody>
              </Card>
            </Col>
          </Row>
        </Container>
      </div>

      {/* Add/Edit Primary Task Modal */}
      <Modal isOpen={modal} toggle={toggleModal} centered>
        <ModalHeader toggle={toggleModal}>
          {isEdit ? "Edit Primary Task" : "Add New Primary Task"}
        </ModalHeader>
        <form onSubmit={handleSubmit}>
          <ModalBody>
            <FormGroup className="mb-3">
              <Label for="subCategoryId">Sub Category</Label>
              <Input
                type="select"
                id="subCategoryId"
                name="subCategoryId"
                value={currentPrimaryTask.subCategoryId}
                onChange={handleInputChange}
                required
              >
                <option value="">Select Sub Category</option>
                {Array.isArray(subCategories) && subCategories.map((subCat) => (
                  <option key={subCat.id} value={subCat.id}>
                    {subCat.name}
                  </option>
                ))}
              </Input>
            </FormGroup>
            <FormGroup className="mb-3">
              <Label for="primaryCategoryName">Primary Category</Label>
              <Input
                type="text"
                id="primaryCategoryName"
                name="primaryCategoryName"
                value={currentPrimaryTask.primaryCategoryName}
                disabled // This field is derived, not directly editable
              />
            </FormGroup>
            <FormGroup className="mb-3">
              <Label for="taskName">Task Name</Label>
              <Input
                type="text"
                id="taskName"
                name="taskName"
                value={currentPrimaryTask.taskName}
                onChange={handleInputChange}
                required
              />
            </FormGroup>
            <FormGroup className="mb-3">
              <Label for="orderNumber">Order Number</Label>
              <Input
                type="number"
                id="orderNumber"
                name="orderNumber"
                value={currentPrimaryTask.orderNumber}
                onChange={handleInputChange}
                required
                min="1"
              />
            </FormGroup>
            <FormGroup className="mb-3">
              <Label for="daysNeeded">Days Needed</Label>
              <Input
                type="number"
                id="daysNeeded"
                name="daysNeeded"
                value={currentPrimaryTask.daysNeeded}
                onChange={handleInputChange}
                required
                min="0"
                step="any" 
              />
            </FormGroup>
            <FormGroup className="mb-3">
              <Label for="manhourNeeded">Manhour Needed</Label>
              <Input
                type="number"
                id="manhourNeeded"
                name="manhourNeeded"
                value={currentPrimaryTask.manhourNeeded}
                onChange={handleInputChange}
                required
                min="0"
                step="any" 
              />
            </FormGroup>
          </ModalBody>
          <ModalFooter>
            <Button color="light" onClick={toggleModal}>
              Cancel
            </Button>
            <Button color="primary" type="submit">
              {isEdit ? "Update Primary Task" : "Add Primary Task"}
            </Button>
          </ModalFooter>
        </form>
      </Modal>

      {/* Custom Confirmation Modal */}
      <Modal isOpen={showConfirmModal} toggle={() => setShowConfirmModal(false)} centered>
        <ModalHeader toggle={() => setShowConfirmModal(false)}>Confirm Action</ModalHeader>
        <ModalBody>{confirmMessage}</ModalBody>
        <ModalFooter>
          <Button color="secondary" onClick={() => setShowConfirmModal(false)}>
            Cancel
          </Button>
          <Button
            color="danger"
            onClick={() => {
              if (confirmCallback) {
                confirmCallback();
              }
              setShowConfirmModal(false);
            }}
          >
            Confirm
          </Button>
        </ModalFooter>
      </Modal>

    

    </React.Fragment>
  );
};

export default AddPrimaryTask;
