import React, { useState, useEffect, useMemo } from 'react';
import {
    Container, Row, Col, Card, CardHeader, CardBody, Table, Button,
    Modal, ModalHeader, ModalBody, ModalFooter, FormGroup, Label, Input,
    Pagination, PaginationItem, PaginationLink
} from 'reactstrap';
import BreadCrumb from '../../Components/Common/BreadCrumb';
// import SimpleBar from 'simplebar-react'; // Remove this import
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

import {
    getAllPrimaryCategories,
    getAllSubCategories,
    createSubCategory,
    updateSubCategory,
    deleteSubCategory
} from '../../api'; // Adjust path if necessary


const ManageSubCategory = () => {
    document.title = "Manage Sub Categories";

    const [primaryCategories, setPrimaryCategories] = useState([]);
    const [subCategories, setSubCategories] = useState([]);

    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(10); // Changed from 5 to 10

    const [modal, setModal] = useState(false);
    const [isEdit, setIsEdit] = useState(false);

    const [currentSubCategory, setCurrentSubCategory] = useState({
        id: null,
        subCategoryName: '',
        primaryCategoryId: '',
        sequenceNumber: ''
    });

    const [deleteModal, setDeleteModal] = useState(false);
    const [subCategoryToDelete, setSubCategoryToDelete] = useState(null);

    const fetchData = async () => {
        setLoading(true);
        setError(null);
        try {
            const [primaryData, subData] = await Promise.all([
                getAllPrimaryCategories(),
                getAllSubCategories()
            ]);
            setPrimaryCategories(primaryData);
            setSubCategories(subData);
            // Ensure currentPage is valid after data refresh
            const newTotalPages = Math.ceil(subData.length / itemsPerPage);
            if (currentPage > newTotalPages && newTotalPages > 0) {
                setCurrentPage(newTotalPages);
            } else if (subData.length === 0) {
                setCurrentPage(1);
            }
        } catch (err) {
            setError(err.message || "An unknown error occurred while fetching data.");
            toast.error(err.message || "Failed to load data.");
            console.error("Failed to fetch data:", err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const totalPages = useMemo(() => Math.ceil(subCategories.length / itemsPerPage), [subCategories.length, itemsPerPage]);

    const currentItems = useMemo(() => {
        const sortedSubCategories = [...subCategories].sort((a, b) => {
            if (a.primaryCategoryId !== b.primaryCategoryId) {
                return a.primaryCategoryId - b.primaryCategoryId;
            }
            return a.sequenceNumber - b.sequenceNumber;
        });
        const indexOfLastItem = currentPage * itemsPerPage;
        const indexOfFirstItem = indexOfLastItem - itemsPerPage;
        return sortedSubCategories.slice(indexOfFirstItem, indexOfLastItem);
    }, [subCategories, currentPage, itemsPerPage]);

    const getPrimaryCategoryName = (id) => {
        const category = primaryCategories.find(cat => cat.id === id);
        return category ? category.name : 'N/A';
    };

    const paginate = (pageNumber) => {
        if (pageNumber > 0 && pageNumber <= totalPages) {
            setCurrentPage(pageNumber);
        }
    };

    const toggleModal = () => {
        setModal(!modal);
        if (modal) {
            setCurrentSubCategory({ id: null, subCategoryName: '', primaryCategoryId: '', sequenceNumber: '' });
            setIsEdit(false);
        }
    };

    const handleEdit = (subCategory) => {
        setCurrentSubCategory({
            id: subCategory.id,
            subCategoryName: subCategory.name,
            primaryCategoryId: subCategory.primaryCategoryId,
            sequenceNumber: subCategory.sequenceNumber
        });
        setIsEdit(true);
        toggleModal();
    };

    const handleDeleteClick = (subCategory) => {
        setSubCategoryToDelete(subCategory);
        setDeleteModal(true);
    };

    const handleCancelDelete = () => {
        setDeleteModal(false);
        setSubCategoryToDelete(null);
    };

    const handleConfirmDelete = async () => {
        if (subCategoryToDelete) {
            try {
                await deleteSubCategory(subCategoryToDelete.id);
                toast.success(`Sub-category "${subCategoryToDelete.name}" deleted successfully!`);
                await fetchData(); // Re-fetch to ensure data consistency and pagination adjustment
                handleCancelDelete();
            } catch (deleteError) {
                console.error("Error soft-deleting sub-category:", deleteError);
                toast.error(deleteError.message || "Failed to delete sub-category.");
                setError(deleteError.message || "Failed to delete sub-category.");
                handleCancelDelete();
            }
        }
    };

    // --- NEW CLIENT-SIDE VALIDATION HELPER ---
    const isConflict = (subCategoryName, sequenceNumber, primaryCategoryId, currentId = null) => {
        const parsedSequenceNumber = parseInt(sequenceNumber);
        const parsedPrimaryCategoryId = parseInt(primaryCategoryId);

        return subCategories.some(subCat => {
            // Skip the current item if we are in edit mode
            if (currentId && subCat.id === currentId) {
                return false;
            }
            // Check for conflict within the same primary category
            return (
                subCat.primaryCategoryId === parsedPrimaryCategoryId &&
                (
                    subCat.name.toLowerCase() === subCategoryName.toLowerCase() ||
                    subCat.sequenceNumber === parsedSequenceNumber
                )
            );
        });
    };
    // --- END NEW CLIENT-SIDE VALIDATION HELPER ---

    const handleSubmit = async (e) => {
        e.preventDefault();

        // Basic validation
        if (!currentSubCategory.subCategoryName || !currentSubCategory.primaryCategoryId || !currentSubCategory.sequenceNumber) {
            toast.error("Please fill in all fields.");
            return;
        }

        // --- CLIENT-SIDE CONFLICT CHECK BEFORE API CALL ---
        if (isConflict(
            currentSubCategory.subCategoryName,
            currentSubCategory.sequenceNumber,
            currentSubCategory.primaryCategoryId,
            isEdit ? currentSubCategory.id : null // Pass ID for edit mode to skip self
        )) {
            toast.error("A sub-category with the same name or sequence number already exists within the selected primary category.");
            return; // Prevent API call
        }
        // --- END CLIENT-SIDE CONFLICT CHECK ---

        try {
            if (isEdit) {
                await updateSubCategory(currentSubCategory.id, {
                    primaryCategoryId: parseInt(currentSubCategory.primaryCategoryId),
                    sequenceNumber: parseInt(currentSubCategory.sequenceNumber),
                    name: currentSubCategory.subCategoryName,
                });
                toast.success("Sub-category updated successfully!");
            } else {
                await createSubCategory({
                    primaryCategoryId: parseInt(currentSubCategory.primaryCategoryId),
                    sequenceNumber: parseInt(currentSubCategory.sequenceNumber),
                    name: currentSubCategory.subCategoryName,
                });
                toast.success("Sub-category added successfully!");
            }

            await fetchData();
            setCurrentSubCategory({ id: null, subCategoryName: '', primaryCategoryId: '', sequenceNumber: '' });
            setIsEdit(false);
            toggleModal();
        } catch (submitError) {
            console.error("Error submitting sub-category:", submitError);
            toast.error(submitError.message || "Failed to save sub-category.");
            setError(submitError.message || "Failed to save sub-category.");
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setCurrentSubCategory({ ...currentSubCategory, [name]: value });
    };

    return (
        <React.Fragment>
            <ToastContainer
                position="top-right"
                autoClose={5000}
                hideProgressBar={false}
                closeOnClick
                pauseOnHover
                draggable
                pauseOnFocusLoss
            />
            <div className="page-content">
                <Container fluid>
                    <BreadCrumb title="Manage Sub Categories" pageTitle="Master" />

                    <Row className="mt-2">
                        <Col lg={12}>
                            <Card>
                                <CardHeader className="d-flex justify-content-between align-items-center">
                                    <h5 className="card-title mb-0">Sub Category List</h5>
                                    <Button color="primary" onClick={() => { setIsEdit(false); toggleModal(); }}>Add New Sub Category</Button>
                                </CardHeader>
                                <CardBody>
                                    {loading ? (
                                        <div className="text-center">Loading sub-categories...</div>
                                    ) : error ? (
                                        <div className="text-center text-danger">Error: {error}</div>
                                    ) : (
                                        // Removed SimpleBar wrapper
                                        <Table className="table-bordered table-nowrap mb-0">
                                            <thead>
                                                <tr>
                                                    <th scope="col">Sequence Number</th>
                                                    <th scope="col">Sub Category Name</th>
                                                    <th scope="col">Primary Category</th>
                                                    <th scope="col" style={{ width: "120px" }}>Actions</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {currentItems.length > 0 ? (
                                                    currentItems.map(subCategory => (
                                                        <tr key={subCategory.id}>
                                                            <td>{subCategory.sequenceNumber}</td>
                                                            <td>{subCategory.name}</td>
                                                            <td>{getPrimaryCategoryName(subCategory.primaryCategoryId)}</td>
                                                            <td>
                                                                <div className="d-flex gap-2">
                                                                    <Button color="info" size="sm" onClick={() => handleEdit(subCategory)}>
                                                                        Edit
                                                                    </Button>
                                                                    <Button color="danger" size="sm" onClick={() => handleDeleteClick(subCategory)}>
                                                                        Delete
                                                                    </Button>
                                                                </div>
                                                            </td>
                                                        </tr>
                                                    ))
                                                ) : (
                                                    <tr>
                                                        <td colSpan="4" className="text-center">No Sub categories found.</td>
                                                    </tr>
                                                )}
                                            </tbody>
                                        </Table>
                                    )}

                                    {/* Pagination Controls */}
                                    {totalPages > 1 && !loading && !error && (
                                        <div className="d-flex justify-content-end mt-3">
                                            <Pagination>
                                                <PaginationItem disabled={currentPage === 1}>
                                                    <PaginationLink previous onClick={() => paginate(currentPage - 1)} />
                                                </PaginationItem>
                                                {[...Array(totalPages)].map((_, i) => (
                                                    <PaginationItem key={i + 1} active={i + 1 === currentPage}>
                                                        <PaginationLink onClick={() => paginate(i + 1)}>
                                                            {i + 1}
                                                        </PaginationLink>
                                                    </PaginationItem>
                                                ))}
                                                <PaginationItem disabled={currentPage === totalPages}>
                                                    <PaginationLink next onClick={() => paginate(currentPage + 1)} />
                                                </PaginationItem>
                                            </Pagination>
                                        </div>
                                    )}
                                </CardBody>
                            </Card>
                        </Col>
                    </Row>
                </Container>
            </div>

            {/* Add/Edit Sub Category Modal */}
            <Modal isOpen={modal} toggle={toggleModal} centered>
                <ModalHeader toggle={toggleModal}>{isEdit ? "Edit Sub Category" : "Add New Sub Category"}</ModalHeader>
                <form onSubmit={handleSubmit}>
                    <ModalBody>
                        <FormGroup className="mb-3">
                            <Label for="subCategoryName">Sub Category Name</Label>
                            <Input
                                type="text"
                                id="subCategoryName"
                                name="subCategoryName"
                                value={currentSubCategory.subCategoryName}
                                onChange={handleInputChange}
                                required
                            />
                        </FormGroup>
                        <FormGroup className="mb-3">
                            <Label for="primaryCategory">Primary Category</Label>
                            <Input
                                type="select"
                                id="primaryCategoryId"
                                name="primaryCategoryId"
                                value={currentSubCategory.primaryCategoryId}
                                onChange={handleInputChange}
                                required
                            >
                                <option value="">Select Primary Category</option>
                                {primaryCategories.map(category => (
                                    <option key={category.id} value={category.id}>
                                        {category.name}
                                    </option>
                                ))}
                            </Input>
                        </FormGroup>
                        <FormGroup className="mb-3">
                            <Label for="sequenceNumber">Sequence Number</Label>
                            <Input
                                type="number"
                                id="sequenceNumber"
                                name="sequenceNumber"
                                value={currentSubCategory.sequenceNumber}
                                onChange={handleInputChange}
                                required
                                min="1"
                            />
                        </FormGroup>
                    </ModalBody>
                    <ModalFooter>
                        <Button color="light" onClick={toggleModal}>Cancel</Button>
                        <Button color="primary" type="submit">{isEdit ? "Update Sub Category" : "Add Sub Category"}</Button>
                    </ModalFooter>
                </form>
            </Modal>

            {/* DELETE CONFIRMATION MODAL */}
            <Modal isOpen={deleteModal} toggle={handleCancelDelete} centered>
                <ModalHeader toggle={handleCancelDelete}>
                    Confirm Deletion
                </ModalHeader>
                <ModalBody>
                    <p>
                        Are you sure you want to soft-delete sub-category{" "}
                        <strong>{subCategoryToDelete?.name}</strong>?
                    </p>
                    <div className="d-flex justify-content-end gap-2 mt-4">
                        <Button color="secondary" onClick={handleCancelDelete}>
                            Cancel
                        </Button>
                        <Button color="danger" onClick={handleConfirmDelete}>
                            Delete
                        </Button>
                    </div>
                </ModalBody>
            </Modal>
        </React.Fragment>
    );
};

export default ManageSubCategory;