import React, { useState, useEffect, useMemo, useCallback } from 'react';
import {
    Container, Row, Col, Card, CardHeader, CardBody, Table, Button,
    Modal, ModalHeader, ModalBody, ModalFooter, FormGroup, Label, Input,
    Pagination, PaginationItem, PaginationLink,
} from 'reactstrap';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import BreadCrumb from '../../Components/Common/BreadCrumb';

import {
    useCategoryData,
    getPrimaryTasks,
    getSubTasks,
    createSubTask,
    updateSubTask,
    deleteSubTask,
} from "../../api";


const ManageSubTask = () => {
    document.title = "Manage Sub Tasks";

    const {
        primaryCategories,
        subCategories,
        getPrimaryCategoryName,
        getSubCategory,
        getSubCategoryName,
        loadingCategories,
        errorCategories,
    } = useCategoryData();

    const [primaryTasks, setPrimaryTasks] = useState([]);
    const [subTasks, setSubTasks] = useState([]);

    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(10); // Set to 10 entries per page

    const [modal, setModal] = useState(false);
    const [isEdit, setIsEdit] = useState(false);

    const [currentSubTask, setCurrentSubTask] = useState({
        id: null,
        primaryTaskId: '',
        subTaskName: '',
        orderNumber: '',
        primaryTaskName: '',
        subCategoryName: '',
        primaryCategoryName: '',
    });


    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [confirmMessage, setConfirmMessage] = useState("");
    const [confirmCallback, setConfirmCallback] = useState(null);

    const showCustomConfirm = useCallback((message, callback) => {
        setConfirmMessage(message);
        setConfirmCallback(() => callback);
        setShowConfirmModal(true);
    }, []);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const fetchedPrimaryTasks = await getPrimaryTasks();
                setPrimaryTasks(fetchedPrimaryTasks);

                const fetchedSubTasks = await getSubTasks();
                setSubTasks(fetchedSubTasks);
            } catch (error) {
                console.error("Failed to fetch data:", error);
                toast.error("Failed to fetch data. Please try again.");
            }
        };
        fetchData();
    }, []);

    useEffect(() => {
        if (
            currentSubTask.primaryTaskId !== '' &&
            !loadingCategories &&
            !errorCategories &&
            primaryTasks.length > 0
        ) {
            const selectedPrimaryTask = primaryTasks.find(
                (task) => task.id === parseInt(currentSubTask.primaryTaskId, 10)
            );

            if (selectedPrimaryTask) {
                const primaryTaskName = selectedPrimaryTask.task_name;
                const subCatName = selectedPrimaryTask.sub_category_name || getSubCategoryName(selectedPrimaryTask.sub_category_id);
                const primaryCatName = selectedPrimaryTask.primary_category_name || (
                    getSubCategory(selectedPrimaryTask.sub_category_id)
                    ? getPrimaryCategoryName(getSubCategory(selectedPrimaryTask.sub_category_id).primary_category_id)
                    : "N/A"
                );

                setCurrentSubTask((prevState) => ({
                    ...prevState,
                    primaryTaskName: primaryTaskName,
                    subCategoryName: subCatName,
                    primaryCategoryName: primaryCatName,
                }));
            } else {
                setCurrentSubTask((prevState) => ({
                    ...prevState,
                    primaryTaskName: "N/A",
                    subCategoryName: "N/A",
                    primaryCategoryName: "N/A",
                }));
            }
        } else if (currentSubTask.primaryTaskId === '') {
            setCurrentSubTask((prevState) => ({
                ...prevState,
                primaryTaskName: "",
                subCategoryName: "",
                primaryCategoryName: "",
            }));
        }
    }, [
        currentSubTask.primaryTaskId,
        primaryTasks,
        getSubCategory,
        getPrimaryCategoryName,
        getSubCategoryName,
        loadingCategories,
        errorCategories,
    ]);


    const totalPages = useMemo(() => Math.ceil(subTasks.length / itemsPerPage), [subTasks.length, itemsPerPage]);

    const currentItems = useMemo(() => {
        const sortedSubTasks = [...subTasks].sort((a, b) => (a.order_number || 0) - (b.order_number || 0));
        const indexOfLastItem = currentPage * itemsPerPage;
        const indexOfFirstItem = indexOfLastItem - itemsPerPage;
        return sortedSubTasks.slice(indexOfFirstItem, indexOfLastItem);
    }, [subTasks, currentPage, itemsPerPage]);

    const paginate = (pageNumber) => {
        if (pageNumber > 0 && pageNumber <= totalPages) {
            setCurrentPage(pageNumber);
        }
    };

    const toggleModal = () => {
        setModal(!modal);
        if (modal) {
            setCurrentSubTask({
                id: null,
                primaryTaskId: '',
                subTaskName: '',
                orderNumber: '',
                primaryTaskName: '',
                subCategoryName: '',
                primaryCategoryName: '',
            });
            setIsEdit(false);
        }
    };

    const handleEdit = (subTask) => {
        setCurrentSubTask({
            id: subTask.id,
            primaryTaskId: subTask.primary_task_id.toString(),
            subTaskName: subTask.sub_task_name,
            orderNumber: subTask.order_number,
            primaryTaskName: subTask.primary_task_name || '',
            subCategoryName: subTask.sub_category_name || '',
            primaryCategoryName: subTask.primary_category_name || '',
        });
        setIsEdit(true);
        toggleModal();
    };

    const handleDelete = async (id) => {
        showCustomConfirm("Are you sure you want to delete this Sub Task?", async () => {
            try {
                await deleteSubTask(id);
                setSubTasks(subTasks.filter(task => task.id !== id));
                const newTotalPages = Math.ceil((subTasks.length - 1) / itemsPerPage);
                if (newTotalPages === 0) {
                    setCurrentPage(1);
                } else if (currentPage > newTotalPages) {
                    setCurrentPage(newTotalPages);
                }
                toast.success("Sub Task deleted successfully!");
            } catch (error) {
                console.error("Failed to delete sub task:", error);
                toast.error("Error deleting sub task. Please try again.");
            }
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (
            !currentSubTask.primaryTaskId ||
            !currentSubTask.subTaskName ||
            currentSubTask.orderNumber === ''
        ) {
            toast.error("Please fill in all required fields.");
            return;
        }

        try {
            const subTaskData = {
                primary_task_id: parseInt(currentSubTask.primaryTaskId, 10),
                sub_task_name: currentSubTask.subTaskName,
                order_number: parseInt(currentSubTask.orderNumber, 10),
            };

            let responseSubTask;
            if (isEdit) {
                responseSubTask = await updateSubTask(currentSubTask.id, subTaskData);
                setSubTasks(subTasks.map(task =>
                    task.id === responseSubTask.id ? responseSubTask : task
                ));
                toast.success("Sub Task updated successfully!");
            } else {
                responseSubTask = await createSubTask(subTaskData);
                setSubTasks([...subTasks, responseSubTask]);
                toast.success("Sub Task added successfully!");
            }

            setCurrentSubTask({
                id: null,
                primaryTaskId: '',
                subTaskName: '',
                orderNumber: '',
                primaryTaskName: '',
                subCategoryName: '',
                primaryCategoryName: '',
            });
            setIsEdit(false);
            toggleModal();
        } catch (error) {
            console.error("Failed to save sub task:", error);
            toast.error("Error saving sub task. Please try again.");
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setCurrentSubTask({ ...currentSubTask, [name]: value });
    };

    const handlePrimaryTaskChange = (e) => {
        const selectedPrimaryTaskId = e.target.value;
        setCurrentSubTask({
            ...currentSubTask,
            primaryTaskId: selectedPrimaryTaskId,
        });
    };

    if (loadingCategories) {
        return (
            <div className="page-content">
                <Container fluid>
                    <p>Loading categories...</p>
                </Container>
            </div>
        );
    }

    if (errorCategories) {
        return (
            <div className="page-content">
                <Container fluid>
                    <p style={{ color: "red" }}>
                        Error loading categories: {errorCategories.message || "Unknown error"}
                    </p>
                </Container>
            </div>
        );
    }

    return (
        <React.Fragment>
            <div className="page-content">
                <ToastContainer
                    position="top-right"
                    autoClose={5000}
                    hideProgressBar={false}
                    closeOnClick
                    pauseOnHover
                    draggable
                    pauseOnFocusLoss
                />
                <Container fluid>
                    <BreadCrumb title="Manage Sub Tasks" pageTitle="Master" />

                    <Row className="mt-2">
                        <Col lg={12}>
                            <Card>
                                <CardHeader className="d-flex justify-content-between align-items-center">
                                    <h5 className="card-title mb-0">Sub Task List</h5>
                                    <Button color="primary" onClick={() => { setIsEdit(false); toggleModal(); }}>Add New Sub Task</Button>
                                </CardHeader>
                                <CardBody>
                                    <div className="table-responsive" style={{ maxHeight: "400px", overflowY: "hidden" }}>
                                        <Table className="table-bordered table-nowrap mb-0">
                                            <thead>
                                                <tr>
                                                    <th scope="col">Order Number</th>
                                                    <th scope="col">Sub Task Name</th>
                                                    <th scope="col">Primary Task Name</th>
                                                    <th scope="col">Sub Category</th>
                                                    <th scope="col">Primary Category</th>
                                                    <th scope="col" style={{ width: "120px" }}>Actions</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {currentItems.length > 0 ? (
                                                    currentItems.map(subTask => (
                                                        <tr key={subTask.id}>
                                                            <td>{subTask.order_number}</td>
                                                            <td>{subTask.sub_task_name}</td>
                                                            <td>{subTask.primary_task_name || 'N/A'}</td>
                                                            <td>{subTask.sub_category_name || 'N/A'}</td>
                                                            <td>{subTask.primary_category_name || 'N/A'}</td>
                                                            <td>
                                                                <div className="d-flex gap-2">
                                                                    <Button color="info" size="sm" onClick={() => handleEdit(subTask)}>
                                                                        Edit
                                                                    </Button>
                                                                    <Button color="danger" size="sm" onClick={() => handleDelete(subTask.id)}>
                                                                        Delete
                                                                    </Button>
                                                                </div>
                                                            </td>
                                                        </tr>
                                                    ))
                                                ) : (
                                                    <tr>
                                                        <td colSpan="6" className="text-center">No Sub Tasks found.</td>
                                                    </tr>
                                                )}
                                            </tbody>
                                        </Table>
                                    </div>

                                    {totalPages > 1 && (
                                        <div className="d-flex justify-content-end mt-3">
                                            <Pagination>
                                                <PaginationItem disabled={currentPage === 1}>
                                                    <PaginationLink previous onClick={() => paginate(currentPage - 1)} />
                                                </PaginationItem>
                                                {[...Array(totalPages)].map((_, i) => (
                                                    <PaginationItem key={i + 1} active={i + 1 === currentPage}>
                                                        <PaginationLink onClick={() => paginate(i + 1)}>
                                                            {i + 1}
                                                        </PaginationLink>
                                                    </PaginationItem>
                                                ))}
                                                <PaginationItem disabled={currentPage === totalPages}>
                                                    <PaginationLink next onClick={() => paginate(currentPage + 1)} />
                                                </PaginationItem>
                                            </Pagination>
                                        </div>
                                    )}
                                </CardBody>
                            </Card>
                        </Col>
                    </Row>
                </Container>
            </div>

            <Modal isOpen={modal} toggle={toggleModal} centered>
                <ModalHeader toggle={toggleModal}>{isEdit ? "Edit Sub Task" : "Add New Sub Task"}</ModalHeader>
                <form onSubmit={handleSubmit}>
                    <ModalBody>
                        <FormGroup className="mb-3">
                            <Label for="primaryTaskId">Primary Task</Label>
                            <Input
                                type="select"
                                id="primaryTaskId"
                                name="primaryTaskId"
                                value={currentSubTask.primaryTaskId}
                                onChange={handlePrimaryTaskChange}
                                required
                            >
                                <option value="">Select Primary Task</option>
                                {Array.isArray(primaryTasks) && primaryTasks.map(task => (
                                    <option key={task.id} value={task.id}>
                                        {task.task_name}
                                    </option>
                                ))}
                            </Input>
                        </FormGroup>
                        <FormGroup className="mb-3">
                            <Label for="subCategoryName">Sub Category</Label>
                            <Input
                                type="text"
                                id="subCategoryName"
                                name="subCategoryName"
                                value={currentSubTask.subCategoryName}
                                readOnly
                            />
                        </FormGroup>
                        <FormGroup className="mb-3">
                            <Label for="primaryCategoryName">Primary Category</Label>
                            <Input
                                type="text"
                                id="primaryCategoryName"
                                name="primaryCategoryName"
                                value={currentSubTask.primaryCategoryName}
                                readOnly
                            />
                        </FormGroup>
                        <FormGroup className="mb-3">
                            <Label for="subTaskName">Sub Task Name</Label>
                            <Input
                                type="text"
                                id="subTaskName"
                                name="subTaskName"
                                value={currentSubTask.subTaskName}
                                onChange={handleInputChange}
                                required
                            />
                        </FormGroup>
                        <FormGroup className="mb-3">
                            <Label for="orderNumber">Order Number</Label>
                            <Input
                                type="number"
                                id="orderNumber"
                                name="orderNumber"
                                value={currentSubTask.orderNumber}
                                onChange={handleInputChange}
                                required
                                min="1"
                            />
                        </FormGroup>
                    </ModalBody>
                    <ModalFooter>
                        <Button color="light" onClick={toggleModal}>Cancel</Button>
                        <Button color="primary" type="submit">{isEdit ? "Update Sub Task" : "Add Sub Task"}</Button>
                    </ModalFooter>
                </form>
            </Modal>

            <Modal isOpen={showConfirmModal} toggle={() => setShowConfirmModal(false)} centered>
                <ModalHeader toggle={() => setShowConfirmModal(false)}>Confirm Action</ModalHeader>
                <ModalBody>{confirmMessage}</ModalBody>
                <ModalFooter>
                    <Button color="light" onClick={() => setShowConfirmModal(false)}>
                        Cancel
                    </Button>
                    <Button
                        color="danger"
                        onClick={() => {
                            if (confirmCallback) {
                                confirmCallback();
                            }
                            setShowConfirmModal(false);
                        }}
                    >
                        Confirm
                    </Button>
                </ModalFooter>
            </Modal>
        </React.Fragment>
    );
};

export default ManageSubTask;





